import { mkdtemp, readFile, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export const FIXED_NOW = new Date('2026-09-30T12:00:00.000Z');

/** Creates an isolated directory; DX_SESSION_TMP is honoured so scratch data stays under the session root. */
export function createTempDir() {
  return mkdtemp(path.join(process.env.DX_SESSION_TMP ?? os.tmpdir(), 'cli-todo-'));
}

export function removeTempDir(dir) {
  return rm(dir, { recursive: true, force: true });
}

export function makeTodo(overrides = {}) {
  return {
    id: 1,
    text: 'Buy groceries',
    completed: false,
    createdAt: '2026-01-01T00:00:00.000Z',
    ...overrides,
  };
}

export function makeState(todos = [], lastId = Math.max(0, ...todos.map((todo) => todo.id))) {
  return { todos, lastId };
}

export async function readJson(filePath) {
  return JSON.parse(await readFile(filePath, 'utf8'));
}

/** True when permission bits are not enforced for this user (root ignores them). */
export const PERMISSIONS_UNENFORCED = process.platform === 'win32' || process.getuid?.() === 0;

