import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { ERROR_CODES } from '../../src/errors.js';
import { DEFAULT_ID_STRATEGY, highestId, ID_STRATEGIES } from '../../src/id-strategies.js';
import { makeState, makeTodo } from '../helpers/fixtures.js';

describe('highestId', () => {
  it('returns 0 for an empty list', () => {
    assert.equal(highestId([]), 0);
  });

  it('returns the largest id regardless of order', () => {
    assert.equal(highestId([makeTodo({ id: 3 }), makeTodo({ id: 7 }), makeTodo({ id: 2 })]), 7);
  });
});

describe('max id strategy', () => {
  const strategy = ID_STRATEGIES.max;

  it('is the default and does not persist a high-water mark', () => {
    assert.equal(DEFAULT_ID_STRATEGY, 'max');
    assert.equal(strategy.persistsLastId, false);
  });

  it('starts at 1 for an empty list', () => {
    assert.equal(strategy.nextId(makeState([])), 1);
  });

  it('assigns one more than the highest existing id, even with gaps', () => {
    assert.equal(strategy.nextId(makeState([makeTodo({ id: 1 }), makeTodo({ id: 5 })])), 6);
  });

  it('reuses the id of a deleted highest todo because it ignores lastId', () => {
    assert.equal(strategy.nextId(makeState([makeTodo({ id: 1 })], 9)), 2);
  });
});

describe('sequence id strategy', () => {
  const strategy = ID_STRATEGIES.sequence;

  it('persists a high-water mark', () => {
    assert.equal(strategy.persistsLastId, true);
  });

  it('starts at 1 for an empty list with no history', () => {
    assert.equal(strategy.nextId(makeState([], 0)), 1);
  });

  it('never reuses an id: continues after lastId when the highest todo was deleted', () => {
    assert.equal(strategy.nextId(makeState([makeTodo({ id: 1 })], 9)), 10);
  });

  it('continues after the highest id when lastId is behind it (hand-edited file)', () => {
    assert.equal(strategy.nextId(makeState([makeTodo({ id: 12 })], 3)), 13);
  });
});

describe('id exhaustion', () => {
  for (const strategy of Object.values(ID_STRATEGIES)) {
    it(`${strategy.name} throws LIMIT_EXCEEDED instead of producing an unsafe integer`, () => {
      const state = makeState([makeTodo({ id: Number.MAX_SAFE_INTEGER })]);
      assert.throws(() => strategy.nextId(state), { code: ERROR_CODES.limitExceeded });
    });
  }
});

