import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { ERROR_CODES, EXIT_CODES } from '../../src/errors.js';
import { ID_STRATEGIES } from '../../src/id-strategies.js';
import {
  addTodo,
  completeTodos,
  countGraphemes,
  deleteTodos,
  normalizeTodoText,
  parseTodoId,
} from '../../src/todos.js';
import { FIXED_NOW, makeState, makeTodo } from '../helpers/fixtures.js';

const ADD_OPTIONS = Object.freeze({
  idStrategy: ID_STRATEGIES.max,
  now: FIXED_NOW,
  maxTextLength: 20,
  maxItems: 3,
});

function sampleState() {
  return makeState([
    makeTodo({ id: 1, text: 'Buy groceries' }),
    makeTodo({ id: 2, text: 'Walk the dog', completed: true }),
    makeTodo({ id: 3, text: 'Call mom' }),
  ]);
}

describe('addTodo', () => {
  it('creates the first todo with id 1, completed false and an ISO createdAt', () => {
    const { state, todo, changed } = addTodo(makeState([]), 'Buy groceries', ADD_OPTIONS);

    assert.deepEqual(todo, {
      id: 1,
      text: 'Buy groceries',
      completed: false,
      createdAt: '2026-09-30T12:00:00.000Z',
    });
    assert.deepEqual(state.todos, [todo]);
    assert.equal(state.lastId, 1);
    assert.equal(changed, true);
  });

  it('assigns the id chosen by the configured strategy', () => {
    const start = makeState([makeTodo({ id: 1 })], 5);

    assert.equal(addTodo(start, 'a', ADD_OPTIONS).todo.id, 2);
    assert.equal(addTodo(start, 'a', { ...ADD_OPTIONS, idStrategy: ID_STRATEGIES.sequence }).todo.id, 6);
  });

  it('trims surrounding whitespace from the text', () => {
    assert.equal(addTodo(makeState([]), '  Buy milk \n', ADD_OPTIONS).todo.text, 'Buy milk');
  });

  it('does not mutate the caller-owned state (side-effect probe)', () => {
    const state = makeState([makeTodo({ id: 1 })]);
    const snapshot = structuredClone(state);

    addTodo(state, 'New todo', ADD_OPTIONS);

    assert.deepEqual(state, snapshot);
  });

  it('rejects adding beyond maxItems with LIMIT_EXCEEDED', () => {
    assert.throws(() => addTodo(sampleState(), 'One too many', ADD_OPTIONS), {
      code: ERROR_CODES.limitExceeded,
      message: /at most 3 todos/,
    });
  });

  it('rejects invalid text before checking the item limit', () => {
    assert.throws(() => addTodo(sampleState(), '   ', ADD_OPTIONS), { code: ERROR_CODES.invalidArgument });
  });
});

describe('normalizeTodoText', () => {
  const limits = { maxTextLength: 5 };

  for (const [label, input] of [
    ['empty string', ''],
    ['spaces only', '     '],
    ['tabs and newlines only', '\t\n\r\n'],
  ]) {
    it(`rejects ${label} as empty with a usage exit code`, () => {
      assert.throws(() => normalizeTodoText(input, limits), {
        code: ERROR_CODES.invalidArgument,
        exitCode: EXIT_CODES.usage,
        message: /cannot be empty/,
      });
    });
  }

  for (const [label, input] of [
    ['an embedded newline', 'a\nb'],
    ['an embedded tab', 'a\tb'],
    ['an ANSI escape sequence', '\u001b[31mred'],
    ['a NUL byte', 'a\u0000b'],
  ]) {
    it(`rejects text containing ${label}`, () => {
      assert.throws(() => normalizeTodoText(input, limits), {
        code: ERROR_CODES.invalidArgument,
        message: /control characters/,
      });
    });
  }

  it('accepts text exactly at the length limit', () => {
    assert.equal(normalizeTodoText('abcde', limits), 'abcde');
  });

  it('rejects text one character over the length limit and reports both lengths', () => {
    assert.throws(() => normalizeTodoText('abcdef', limits), {
      code: ERROR_CODES.invalidArgument,
      message: /6 characters.*maximum is 5/,
    });
  });

  it('counts an emoji with a skin tone or ZWJ family as one character', () => {
    const text = '👍🏽👨‍👩‍👧日本語';
    assert.equal(countGraphemes(text), 5);
    assert.equal(normalizeTodoText(text, limits), text);
  });

  it('normalizes decomposed accents to NFC so equal-looking text is stored identically', () => {
    assert.equal(normalizeTodoText('Cafe\u0301', limits), 'Caf\u00e9');
  });
});

describe('parseTodoId', () => {
  for (const [input, expected] of [
    ['1', 1],
    ['42', 42],
    ['007', 7],
    [' 3 ', 3],
    [String(Number.MAX_SAFE_INTEGER), Number.MAX_SAFE_INTEGER],
  ]) {
    it(`parses ${JSON.stringify(input)} as ${expected}`, () => {
      assert.equal(parseTodoId(input), expected);
    });
  }

  for (const input of ['0', '-1', '+1', '1.5', '1e3', '0x10', 'abc', '', '   ', '١', '9007199254740992']) {
    it(`rejects ${JSON.stringify(input)} with INVALID_ARGUMENT`, () => {
