import { ERROR_CODES, TodoError } from './errors.js';

/**
 * Highest id in the list, or 0 when the list is empty.
 * @param {readonly import('./todos.js').Todo[]} todos
 */
export function highestId(todos) {
  let highest = 0;
  for (const todo of todos) {
    if (todo.id > highest) highest = todo.id;
  }
  return highest;
}

function successor(id) {
  const next = id + 1;
  if (!Number.isSafeInteger(next)) {
    throw new TodoError(`Cannot assign a new id: ${id} is the largest id that can be stored exactly`, {
      code: ERROR_CODES.limitExceeded,
    });
  }
  return next;
}

/**
 * @typedef {object} IdStrategy
 * @property {string} name
 * @property {boolean} persistsLastId Whether todos.json must record the high-water mark for this strategy to work.
 * @property {(state: import('./todos.js').TodoState) => number} nextId
 */

/**
 * The two ways "auto-incrementing" can be read. Both hand out increasing ids;
 * they differ only once the todo holding the highest id is deleted.
 * @type {Readonly<Record<'max' | 'sequence', IdStrategy>>}
 */
export const ID_STRATEGIES = Object.freeze({
  // Like SQLite's default rowid: highest remaining id + 1. Needs no extra state,
  // so todos.json stays a plain array, but deleting the newest todo frees its id.
  max: Object.freeze({
    name: 'max',
    persistsLastId: false,
    nextId: (state) => successor(highestId(state.todos)),
  }),
  // Like SQLite's AUTOINCREMENT: ids are never handed out twice, at the cost of
  // storing `lastId` next to the todos.
  sequence: Object.freeze({
    name: 'sequence',
    persistsLastId: true,
    nextId: (state) => successor(Math.max(state.lastId, highestId(state.todos))),
  }),
});

/** Strategy used when TODO_ID_STRATEGY is not set. */
export const DEFAULT_ID_STRATEGY = 'max';

