import { describe, it } from 'node:test';

import {
  EMPTY_LIST_MESSAGE,
  formatSummary,
  formatTodoLine,
  formatTodoList,
  sanitizeForTerminal,
  STATUS_MARKERS,
} from '../../src/format.js';
import { makeTodo } from '../helpers/fixtures.js';

describe('formatTodoLine', () => {
  it('shows id, the [ ] marker and text for a pending todo', () => {
    assert.equal(formatTodoLine(makeTodo({ id: 1, text: 'Buy groceries' })), '1. [ ] Buy groceries');
  });

  it('shows the [x] marker for a completed todo', () => {
    assert.equal(formatTodoLine(makeTodo({ id: 2, text: 'Walk the dog', completed: true })), '2. [x] Walk the dog');
    assert.deepEqual(STATUS_MARKERS, { done: '[x]', pending: '[ ]' });
  });

  it('right-aligns the id to the requested width', () => {
    assert.equal(formatTodoLine(makeTodo({ id: 7 }), 3), '  7. [ ] Buy groceries');
  });
});

describe('formatTodoList', () => {
  it('returns the empty-list message for no todos', () => {
    assert.equal(formatTodoList([]), EMPTY_LIST_MESSAGE);
  });

  it('lists todos sorted by id with aligned ids, then a pending/done summary', () => {
    const output = formatTodoList([
      makeTodo({ id: 10, text: 'Ten', completed: true }),
      makeTodo({ id: 9, text: 'Nine' }),
    ]);

    assert.equal(output, [' 9. [ ] Nine', '10. [x] Ten', '', '2 todos: 1 pending, 1 done'].join('\n'));
  });

  it('does not reorder the caller-owned array (side-effect probe)', () => {
    const todos = [makeTodo({ id: 2 }), makeTodo({ id: 1 })];

    formatTodoList(todos);

    assert.deepEqual(todos.map((todo) => todo.id), [2, 1]);
  });
});

describe('formatSummary', () => {
  it('uses the singular for one todo', () => {
    assert.equal(formatSummary([makeTodo()]), '1 todo: 1 pending, 0 done');
  });

  it('counts pending and done todos', () => {
    const todos = [makeTodo({ id: 1 }), makeTodo({ id: 2, completed: true }), makeTodo({ id: 3, completed: true })];
    assert.equal(formatSummary(todos), '3 todos: 1 pending, 2 done');
  });
});

describe('sanitizeForTerminal', () => {
  it('escapes control characters so stored text cannot inject terminal escape sequences', () => {
    assert.equal(sanitizeForTerminal('red\u001b[31m\nnext'), 'red\\u001b[31m\\u000anext');
  });

  it('leaves printable unicode untouched', () => {
    const text = 'Café 日本語 👨‍👩‍👧 مرحبا';
    assert.equal(sanitizeForTerminal(text), text);
  });
});

