import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { CONFIG_ENV_VARS, DEFAULT_CONFIG, loadConfig } from '../../src/config.js';
import { ERROR_CODES, EXIT_CODES } from '../../src/errors.js';
import { ID_STRATEGIES } from '../../src/id-strategies.js';

describe('loadConfig', () => {
  it('uses the defaults when no variables are set', () => {
    assert.deepEqual(loadConfig({}), {
      idStrategy: ID_STRATEGIES.max,
      maxTextLength: DEFAULT_CONFIG.maxTextLength,
      maxItems: DEFAULT_CONFIG.maxItems,
      lockTimeoutMs: DEFAULT_CONFIG.lockTimeoutMs,
    });
  });

  it('treats empty and whitespace-only values as unset', () => {
    const env = Object.fromEntries(Object.values(CONFIG_ENV_VARS).map((name) => [name, '  ']));
    assert.deepEqual(loadConfig(env), loadConfig({}));
  });

  it('reads every setting from its environment variable', () => {
    const config = loadConfig({
      TODO_ID_STRATEGY: 'sequence',
      TODO_MAX_TEXT_LENGTH: '80',
      TODO_MAX_ITEMS: '2',
      TODO_LOCK_TIMEOUT_MS: '0',
    });

    assert.equal(config.idStrategy, ID_STRATEGIES.sequence);
    assert.equal(config.maxTextLength, 80);
    assert.equal(config.maxItems, 2);
    assert.equal(config.lockTimeoutMs, 0);
  });

  it('accepts the strategy name in any case with surrounding spaces', () => {
    assert.equal(loadConfig({ TODO_ID_STRATEGY: ' Sequence ' }).idStrategy, ID_STRATEGIES.sequence);
  });

  it('rejects an unknown strategy, naming the variable and the allowed values', () => {
    assert.throws(() => loadConfig({ TODO_ID_STRATEGY: 'uuid' }), {
      code: ERROR_CODES.invalidConfig,
      exitCode: EXIT_CODES.usage,
      message: /TODO_ID_STRATEGY="uuid".*max, sequence/,
    });
  });

  it('does not resolve inherited object keys as strategies', () => {
    assert.throws(() => loadConfig({ TODO_ID_STRATEGY: 'constructor' }), { code: ERROR_CODES.invalidConfig });
  });

  for (const [name, value] of [
    ['TODO_MAX_TEXT_LENGTH', 'abc'],
    ['TODO_MAX_TEXT_LENGTH', '0'],
    ['TODO_MAX_TEXT_LENGTH', '1.5'],
    ['TODO_MAX_ITEMS', '-3'],
    ['TODO_MAX_ITEMS', '10items'],
    ['TODO_MAX_ITEMS', '99999999999999999999'],
    ['TODO_LOCK_TIMEOUT_MS', '-1'],
  ]) {
    it(`rejects ${name}=${JSON.stringify(value)} with INVALID_CONFIG`, () => {
      assert.throws(() => loadConfig({ [name]: value }), {
        code: ERROR_CODES.invalidConfig,
        message: new RegExp(`^Invalid ${name}=`),
      });
    });
  }
});

