import assert from 'node:assert/strict';
import { chmod, lstat, mkdir, readdir, readFile, stat, symlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { afterEach, beforeEach, describe, it } from 'node:test';

import { ERROR_CODES } from '../../src/errors.js';
import {
  readTodoState,
  serializeTodoState,
  TODO_FILE_NAME,
  updateTodoState,
  writeTodoState,
} from '../../src/storage.js';
import {
  createTempDir,
  makeState,
  makeTodo,
  PERMISSIONS_UNENFORCED,
  readJson,
  removeTempDir,
} from '../helpers/fixtures.js';

const PERMISSION_BITS = 0o777;

let dir;
let file;

beforeEach(async () => {
  dir = await createTempDir();
  file = path.join(dir, TODO_FILE_NAME);
});

afterEach(async () => {
  await chmod(dir, 0o700);
  await removeTempDir(dir);
});

async function writeRaw(content) {
  await writeFile(file, typeof content === 'string' ? content : JSON.stringify(content));
}

describe('readTodoState', () => {
  it('returns an empty state when todos.json does not exist', async () => {
    assert.deepEqual(await readTodoState(file), { todos: [], lastId: 0 });
  });

  for (const [label, content] of [
    ['an empty file', ''],
    ['a whitespace-only file', ' \n\t\n'],
  ]) {
    it(`treats ${label} as an empty list`, async () => {
      await writeRaw(content);
      assert.deepEqual(await readTodoState(file), { todos: [], lastId: 0 });
    });
  }

  it('reads the plain array format and derives lastId from the highest id', async () => {
    const todos = [makeTodo({ id: 1 }), makeTodo({ id: 4, completed: true })];
    await writeRaw(todos);

    assert.deepEqual(await readTodoState(file), { todos, lastId: 4 });
  });

  it('reads the object format and keeps the stored lastId', async () => {
    const todos = [makeTodo({ id: 2 })];
    await writeRaw({ lastId: 9, todos });

    assert.deepEqual(await readTodoState(file), { todos, lastId: 9 });
  });

  it('raises a stored lastId that is behind the highest id', async () => {
    await writeRaw({ lastId: 1, todos: [makeTodo({ id: 6 })] });

    assert.equal((await readTodoState(file)).lastId, 6);
  });

  it('ignores a UTF-8 byte order mark written by some editors', async () => {
    await writeRaw(`﻿${JSON.stringify([makeTodo()])}`);

    assert.equal((await readTodoState(file)).todos.length, 1);
  });

  it('reports invalid JSON as CORRUPT_FILE naming the file', async () => {
    await writeRaw('[{"id": 1,');

    await assert.rejects(readTodoState(file), (error) => {
      assert.equal(error.code, ERROR_CODES.corruptFile);
      assert.match(error.message, /not valid JSON/);
      assert.ok(error.message.includes(file));
      return true;
    });
  });

  const valid = makeTodo();
  for (const [label, document, message] of [
    ['a JSON object without a todos array', { items: [] }, /expected an array of todos/],
    ['a JSON string', 'hello', /expected an array of todos/],
    ['JSON null', null, /expected an array of todos/],
    ['an item that is not an object', [42], /item at index 0 is not an object/],
    ['a missing id', [{ ...valid, id: undefined }], /index 0 has an invalid "id"/],
    ['a zero id', [{ ...valid, id: 0 }], /"id".*got 0/],
    ['a numeric string id', [{ ...valid, id: '1' }], /"id".*got "1"/],
    ['a non-string text', [{ ...valid, text: 5 }], /"text"/],
    ['a string completed flag', [{ ...valid, completed: 'yes' }], /"completed"/],
    ['a non-ISO createdAt', [{ ...valid, createdAt: 'yesterday' }], /"createdAt"/],
    ['an out-of-range createdAt', [{ ...valid, createdAt: '2026-13-01T00:00:00Z' }], /"createdAt"/],
    ['duplicate ids', [valid, { ...valid, text: 'Again' }], /duplicate id 1 at index 1/],
    ['a negative lastId', { lastId: -1, todos: [] }, /"lastId"/],
  ]) {
    it(`reports ${label} as CORRUPT_FILE`, async () => {
      await writeRaw(document);
      await assert.rejects(readTodoState(file), { code: ERROR_CODES.corruptFile, message });
    });
  }

  it('reports a todos.json that is a directory as STORAGE', async () => {
    await mkdir(file);
    await assert.rejects(readTodoState(file), { code: ERROR_CODES.storage, message: /Could not read/ });
  });

  it('reports an unreadable todos.json as STORAGE', { skip: PERMISSIONS_UNENFORCED }, async () => {
    await writeRaw([]);
    await chmod(file, 0o000);

    await assert.rejects(readTodoState(file), { code: ERROR_CODES.storage, message: /EACCES/ });
  });
});

describe('writeTodoState', () => {
  const state = makeState([makeTodo({ id: 1 }), makeTodo({ id: 3, completed: true })], 5);

  it('writes a plain array with 2-space indentation and a trailing newline for the max strategy', async () => {
    await writeTodoState(file, state, { persistLastId: false });

    assert.equal(await readFile(file, 'utf8'), `${JSON.stringify(state.todos, null, 2)}\n`);
    assert.equal(serializeTodoState(state, { persistLastId: false }), await readFile(file, 'utf8'));
  });

  it('writes an object with lastId for the sequence strategy', async () => {
    await writeTodoState(file, state, { persistLastId: true });

    assert.deepEqual(await readJson(file), { lastId: 5, todos: state.todos });
  });

  it('round-trips through readTodoState and preserves fields it does not know about', async () => {
    const withExtra = makeState([makeTodo({ id: 2, priority: 'high' })], 2);

    await writeTodoState(file, withExtra, { persistLastId: false });

    assert.deepEqual(await readTodoState(file), withExtra);
  });

  it('replaces the file without leaving temporary files behind', async () => {
    await writeTodoState(file, state, { persistLastId: false });
    await writeTodoState(file, makeState([]), { persistLastId: false });

    assert.deepEqual(await readdir(dir), [TODO_FILE_NAME]);
    assert.deepEqual(await readJson(file), []);
  });

  it('keeps the permissions of an existing todos.json', { skip: PERMISSIONS_UNENFORCED }, async () => {
    await writeRaw([]);
    await chmod(file, 0o600);

    await writeTodoState(file, state, { persistLastId: false });

    assert.equal((await stat(file)).mode & PERMISSION_BITS, 0o600);
  });

  it('writes through a symlinked todos.json instead of replacing the link', async () => {
    const target = path.join(dir, 'real-todos.json');
    await writeFile(target, '[]');
    await symlink(target, file);

    await writeTodoState(file, state, { persistLastId: false });

    assert.ok((await lstat(file)).isSymbolicLink());
    assert.deepEqual(await readJson(target), state.todos);
  });

  it('reports a missing directory as STORAGE', async () => {
    const missing = path.join(dir, 'no-such-dir', TODO_FILE_NAME);
    await assert.rejects(writeTodoState(missing, state, { persistLastId: false }), {
      code: ERROR_CODES.storage,
      message: /Could not save todos/,
    });
  });

  it('reports a read-only directory as STORAGE and keeps the old contents', { skip: PERMISSIONS_UNENFORCED }, async () => {
    await writeRaw([]);
    await chmod(dir, 0o500);

    await assert.rejects(writeTodoState(file, state, { persistLastId: false }), { code: ERROR_CODES.storage });
    assert.deepEqual(await readJson(file), []);
  });
});

describe('updateTodoState', () => {
  const options = { persistLastId: false, lockTimeoutMs: 2_000 };

  function appendTodo(text) {
    return (state) => {
      const id = state.todos.length + 1;
      return { state: { ...state, todos: [...state.todos, makeTodo({ id, text })] }, changed: true, id };
    };
  }

  it('applies the mutation, saves it and returns the mutation outcome', async () => {
    const outcome = await updateTodoState(file, appendTodo('first'), options);

    assert.equal(outcome.id, 1);
    assert.deepEqual((await readJson(file)).map((todo) => todo.text), ['first']);
  });

  it('does not rewrite the file when the mutation reports no change', async () => {
    const original = JSON.stringify([makeTodo()]);
    await writeRaw(original);

    await updateTodoState(file, (state) => ({ state, changed: false }), options);

    assert.equal(await readFile(file, 'utf8'), original);
  });

  it('does not create todos.json when nothing changed', async () => {
    await updateTodoState(file, (state) => ({ state, changed: false }), options);

    assert.deepEqual(await readdir(dir), []);
  });

  it('leaves the file untouched and releases the lock when the mutation throws', async () => {
    await writeRaw([makeTodo()]);
    const failure = new Error('mutation failed');

    await assert.rejects(
      updateTodoState(file, () => {
        throw failure;
      }, options),
      failure,
    );

    assert.deepEqual(await readdir(dir), [TODO_FILE_NAME]);
    assert.deepEqual(await readJson(file), [makeTodo()]);
  });

  it('serializes concurrent in-process updates so no write is lost', async () => {
    const count = 25;

    await Promise.all(Array.from({ length: count }, (_, index) => updateTodoState(file, appendTodo(`t${index}`), options)));

    const ids = (await readJson(file)).map((todo) => todo.id);
    assert.deepEqual(ids, Array.from({ length: count }, (_, index) => index + 1));
  });
});

