import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { readdir, readFile, stat, utimes, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, it } from 'node:test';
import { setTimeout as delay } from 'node:timers/promises';
import { randomUUID } from 'node:crypto';

import { ERROR_CODES } from '../../src/errors.js';
import { formatLockOwner, withFileLock } from '../../src/lock.js';
import { createTempDir, removeTempDir } from '../helpers/fixtures.js';

const SHORT_TIMEOUT = Object.freeze({ timeoutMs: 60, retryDelayMs: 5 });

let dir;
let lockPath;

beforeEach(async () => {
  dir = await createTempDir();
  lockPath = path.join(dir, 'todos.json.lock');
});

afterEach(() => removeTempDir(dir));

function lockContent(overrides = {}) {
  return formatLockOwner({ pid: process.pid, hostname: os.hostname(), token: randomUUID(), ...overrides });
}

async function exitedProcessId() {
  const child = spawn(process.execPath, ['-e', ''], { stdio: 'ignore' });
  await once(child, 'exit');
  return child.pid;
}

describe('withFileLock', () => {
  it('holds the lock file while the callback runs and removes it afterwards', async () => {
    const result = await withFileLock(lockPath, async () => {
      assert.ok((await stat(lockPath)).isFile());
      return 'done';
    });

    assert.equal(result, 'done');
    assert.deepEqual(await readdir(dir), []);
  });

  it('removes the lock and rethrows the original error when the callback throws', async () => {
    const failure = new Error('boom');

    await assert.rejects(
      withFileLock(lockPath, async () => {
        throw failure;
      }),
      failure,
    );
    assert.deepEqual(await readdir(dir), []);
  });

  it('serializes concurrent callers so critical sections never overlap', async () => {
    let active = 0;
    let maxActive = 0;
    let finished = 0;

    await Promise.all(
      Array.from({ length: 10 }, () =>
        withFileLock(
          lockPath,
          async () => {
            active += 1;
            maxActive = Math.max(maxActive, active);
            await delay(2);
            active -= 1;
            finished += 1;
          },
          { retryDelayMs: 2 },
        ),
      ),
    );

    assert.equal(maxActive, 1);
    assert.equal(finished, 10);
  });

  it('times out with LOCK_TIMEOUT while a live process holds the lock, leaving that lock alone', async () => {
    const held = lockContent();
    await writeFile(lockPath, held);
    let ran = false;

    await assert.rejects(
      withFileLock(lockPath, async () => {
        ran = true;
      }, SHORT_TIMEOUT),
      { code: ERROR_CODES.lockTimeout, message: /Timed out after 60 ms/ },
    );

    assert.equal(ran, false);
    assert.equal(await readFile(lockPath, 'utf8'), held);
  });

  it('takes over a lock older than staleMs even if its owner looks alive', async () => {
    await writeFile(lockPath, lockContent());
    const longAgo = new Date(Date.now() - 60_000);
    await utimes(lockPath, longAgo, longAgo);

    const result = await withFileLock(lockPath, async () => 'acquired', { ...SHORT_TIMEOUT, staleMs: 1_000 });

    assert.equal(result, 'acquired');
  });

  it('takes over a fresh lock left by a process on this host that has exited', async () => {
    await writeFile(lockPath, lockContent({ pid: await exitedProcessId() }));

    const result = await withFileLock(lockPath, async () => 'acquired', SHORT_TIMEOUT);

    assert.equal(result, 'acquired');
  });

  it('does not judge a lock from another host by its pid', async () => {
    await writeFile(lockPath, lockContent({ pid: await exitedProcessId(), hostname: 'some-other-host' }));

    await assert.rejects(withFileLock(lockPath, async () => {}, SHORT_TIMEOUT), { code: ERROR_CODES.lockTimeout });
  });

  it('does not take over a fresh lock whose owner has not finished writing it', async () => {
    await writeFile(lockPath, '');

    await assert.rejects(withFileLock(lockPath, async () => {}, SHORT_TIMEOUT), { code: ERROR_CODES.lockTimeout });
  });

  it('reports LOCK_LOST and keeps the new owner lock when the lock was replaced mid-callback', async () => {
    const intruder = lockContent({ pid: 1 });

    await assert.rejects(
      withFileLock(lockPath, async () => {
        await writeFile(lockPath, intruder);
      }),
      { code: ERROR_CODES.lockLost },
    );
    assert.equal(await readFile(lockPath, 'utf8'), intruder);
  });

  it('reports a lock that cannot be created as STORAGE', async () => {
    const unreachable = path.join(dir, 'missing-dir', 'todos.json.lock');

    await assert.rejects(withFileLock(unreachable, async () => {}), {
      code: ERROR_CODES.storage,
      message: /Could not create lock file/,
    });
  });
});

