// Advisory lock so that two todo commands started at the same time cannot
// both read todos.json, change it, and have the second write discard the first.
import { randomUUID } from 'node:crypto';
import { open, readFile, rm, stat } from 'node:fs/promises';
import os from 'node:os';
import { setTimeout as delay } from 'node:timers/promises';

import { ERROR_CODES, TodoError } from './errors.js';

/**
 * Defaults for withFileLock. A command holds the lock for a few milliseconds,
 * so a lock file untouched for staleMs belongs to a process that died.
 */
export const DEFAULT_LOCK_OPTIONS = Object.freeze({
  timeoutMs: 5_000,
  staleMs: 10_000,
  retryDelayMs: 20,
});

const MAX_PID = 2 ** 31 - 1;
// The trailing newline is written last, so its absence means the owner is
// still writing the file and its pid cannot be trusted yet.
const LOCK_CONTENT = /^([1-9]\d{0,9}) (\S+) (.+)\n$/;

/**
 * Serializes a lock owner as `<pid> <token> <hostname>\n`.
 * @param {{ pid: number, token: string, hostname: string }} owner
 */
export function formatLockOwner({ pid, token, hostname }) {
  return `${pid} ${token} ${hostname}\n`;
}

function parseLockOwner(content) {
  const match = LOCK_CONTENT.exec(content);
  if (match === null || Number(match[1]) > MAX_PID) return null;
  return { pid: Number(match[1]), token: match[2], hostname: match[3] };
}

function isProcessAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    if (error.code === 'ESRCH') return false;
    // EPERM: the process exists but belongs to another user.
    if (error.code === 'EPERM') return true;
    throw error;
  }
}

function storageError(action, lockPath, error) {
  return new TodoError(`Could not ${action} lock file ${lockPath}: ${error.message}`, {
    code: ERROR_CODES.storage,
    cause: error,
  });
}

async function tryCreate(lockPath, content) {
  let handle;
  try {
    handle = await open(lockPath, 'wx');
  } catch (error) {
    if (error.code === 'EEXIST') return false;
    throw storageError('create', lockPath, error);
  }
  try {
    await handle.writeFile(content, 'utf8');
  } catch (error) {
    await handle.close();
    await rm(lockPath, { force: true });
    throw storageError('write', lockPath, error);
  }
  await handle.close();
  return true;
}

/** @returns {Promise<'released' | 'abandoned' | 'held'>} */
async function inspect(lockPath, staleMs) {
  let info;
  let content;
  try {
    [info, content] = await Promise.all([stat(lockPath), readFile(lockPath, 'utf8')]);
  } catch (error) {
    if (error.code === 'ENOENT') return 'released';
    throw storageError('inspect', lockPath, error);
  }
  if (Date.now() - info.mtimeMs > staleMs) return 'abandoned';
  const owner = parseLockOwner(content);
  // A pid only identifies a process on the machine that wrote it.
  if (owner !== null && owner.hostname === os.hostname() && !isProcessAlive(owner.pid)) return 'abandoned';
  return 'held';
}

async function acquire(lockPath, { timeoutMs, staleMs, retryDelayMs }) {
  const token = randomUUID();
  const content = formatLockOwner({ pid: process.pid, token, hostname: os.hostname() });
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    if (await tryCreate(lockPath, content)) return token;
    const status = await inspect(lockPath, staleMs);
    if (status === 'abandoned') {
      await rm(lockPath, { force: true });
    } else if (status === 'held') {
      if (Date.now() >= deadline) {
        throw new TodoError(
          `Timed out after ${timeoutMs} ms waiting for ${lockPath}. Another todo command may still be running; if none is, delete the lock file.`,
          { code: ERROR_CODES.lockTimeout },
        );
      }
      // Jitter keeps processes that collided once from retrying in lockstep.
      await delay(retryDelayMs + Math.floor(Math.random() * retryDelayMs));
    }
  }
}

async function release(lockPath, token) {
  let content = '';
  try {
    content = await readFile(lockPath, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT') throw storageError('read', lockPath, error);
  }
  // Another process judged our lock stale and replaced it, so the two
  // critical sections may have overlapped. Leave its lock in place.
  if (parseLockOwner(content)?.token !== token) {
    throw new TodoError(
      `Lost the lock on ${lockPath}: another process took it over while this command ran, so its change and this one may have overwritten each other.`,
      { code: ERROR_CODES.lockLost },
    );
  }
  try {
    await rm(lockPath, { force: true });
  } catch (error) {
    throw storageError('remove', lockPath, error);
  }
}

/**
 * Runs `callback` while holding an exclusive lock file at `lockPath`, waiting
 * up to `timeoutMs` for another holder to finish. Locks whose owner exited, or
 * that are older than `staleMs`, are taken over.
 * @template T
 * @param {string} lockPath
 * @param {() => Promise<T>} callback
 * @param {Partial<typeof DEFAULT_LOCK_OPTIONS>} [options]
 * @returns {Promise<T>}
 * @throws {TodoError} LOCK_TIMEOUT, LOCK_LOST or STORAGE.
 */
export async function withFileLock(lockPath, callback, options = {}) {
  const token = await acquire(lockPath, { ...DEFAULT_LOCK_OPTIONS, ...options });
  let result;
  try {
    result = await callback();
  } catch (error) {
    await release(lockPath, token).catch((releaseError) => {
      throw new AggregateError([error, releaseError], `${error.message}; also, ${releaseError.message}`);
    });
    throw error;
  }
  await release(lockPath, token);
  return result;
}

