 * concurrent commands cannot lose each other's changes. The file is only
 * rewritten when the mutation reports `changed`.
 * @template {{ state: import('./todos.js').TodoState, changed: boolean }} Outcome
 * @param {string} filePath
 * @param {(state: import('./todos.js').TodoState) => Outcome} mutate Must be synchronous and pure.
 * @param {{ persistLastId: boolean, lockTimeoutMs: number }} options
 * @returns {Promise<Outcome>}
 */
export async function updateTodoState(filePath, mutate, { persistLastId, lockTimeoutMs }) {
  return withFileLock(
    `${filePath}.lock`,
    async () => {
      const outcome = mutate(await readTodoState(filePath));
      if (outcome.changed) await writeTodoState(filePath, outcome.state, { persistLastId });
      return outcome;
    },
    { timeoutMs: lockTimeoutMs },
  );
}

