import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

import { run } from '../../src/cli.js';
import { FIXED_NOW } from './fixtures.js';

export const INDEX_PATH = fileURLToPath(new URL('../../index.js', import.meta.url));

const PROCESS_TIMEOUT_MS = 20_000;

// Child processes must not see the developer's TODO_* settings or the test
// runner's own context variables.
const INHERITED_ENV = Object.fromEntries(
  Object.entries(process.env).filter(([name]) => !name.startsWith('TODO_') && !name.startsWith('NODE_TEST')),
);

function collector() {
  const chunks = [];
  return {
    write(chunk) {
      chunks.push(String(chunk));
      return true;
    },
    text: () => chunks.join(''),
  };
}

/** Runs the CLI in-process with captured output and a fixed clock. */
export async function runCli(argv, { cwd, env = {}, now = () => FIXED_NOW } = {}) {
  const stdout = collector();
  const stderr = collector();
  const code = await run(argv, { cwd, env, stdout, stderr, now });
  return { code, stdout: stdout.text(), stderr: stderr.text() };
}

/** Runs `node index.js ...argv` as a real child process. */
export function runNode(argv, { cwd, env = {}, timeoutMs = PROCESS_TIMEOUT_MS } = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [INDEX_PATH, ...argv], {
      cwd,
      env: { ...INHERITED_ENV, ...env },
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: timeoutMs,
    });
    const stdout = [];
    const stderr = [];
    child.stdout.on('data', (chunk) => stdout.push(chunk));
    child.stderr.on('data', (chunk) => stderr.push(chunk));
    child.on('error', reject);
    child.on('close', (code, signal) => {
      if (signal !== null) {
        reject(new Error(`node index.js ${argv.join(' ')} was killed by ${signal} (timeout ${timeoutMs} ms)`));
        return;
      }
      resolve({ code, stdout: Buffer.concat(stdout).toString('utf8'), stderr: Buffer.concat(stderr).toString('utf8') });
    });
  });
}

