  it('runs the add, list, complete and delete lifecycle in real processes', async () => {
    const steps = [
      [['list'], 'No todos yet. Add one with: node index.js add "Buy groceries"\n'],
      [['add', 'Buy groceries'], 'Added todo #1: Buy groceries\n'],
      [['add', 'Walk the dog'], 'Added todo #2: Walk the dog\n'],
      [['list'], '1. [ ] Buy groceries\n2. [ ] Walk the dog\n\n2 todos: 2 pending, 0 done\n'],
      [['complete', '1'], 'Completed todo #1: Buy groceries\n'],
      [['list'], '1. [x] Buy groceries\n2. [ ] Walk the dog\n\n2 todos: 1 pending, 1 done\n'],
      [['delete', '2'], 'Deleted todo #2: Walk the dog\n'],
      [['list'], '1. [x] Buy groceries\n\n1 todo: 0 pending, 1 done\n'],
    ];

    // Each step depends on the file state left by the previous one.
    for (const [argv, expected] of steps) {
      const result = await node(...argv);
      assert.deepEqual(result, { code: 0, stdout: expected, stderr: '' }, `node index.js ${argv.join(' ')}`);
    }
  });

  it('stores exactly id, text, completed and a current ISO createdAt in ./todos.json', async () => {
    const before = Date.now();
    await node('add', 'Buy groceries');
    const after = Date.now();

    const [todo] = await readJson(path.join(cwd, 'todos.json'));
    assert.deepEqual(Object.keys(todo).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(todo.id, 1);
    assert.equal(todo.text, 'Buy groceries');
    assert.equal(todo.completed, false);
    assert.equal(new Date(todo.createdAt).toISOString(), todo.createdAt);
    assert.ok(Date.parse(todo.createdAt) >= before - 1_000 && Date.parse(todo.createdAt) <= after + 1_000);
  });

  for (const [argv, exitCode, stderr] of [
    [[], 2, /Missing command/],
    [['frobnicate'], 2, /Unknown command "frobnicate"/],
    [['add'], 2, /Missing todo text/],
    [['complete'], 2, /Missing todo id/],
    [['delete'], 2, /Missing todo id/],
    [['complete', 'abc'], 2, /Invalid todo id "abc"/],
    [['delete', '1'], 1, /No todo with id #1 \(the list is empty\)/],
  ]) {
    it(`exits ${exitCode} for "${argv.join(' ') || '(no arguments)'}" with an error on stderr only`, async () => {
      const result = await node(...argv);

      assert.equal(result.code, exitCode);
      assert.equal(result.stdout, '');
      assert.match(result.stderr, stderr);
    });
  }

  it('keeps every todo when several processes add at the same time (parallel)', async () => {
    const count = 8;

    const results = await Promise.all(Array.from({ length: count }, (_, index) => node('add', `task ${index}`)));

    assert.ok(results.every((result) => result.code === 0), results.map((result) => result.stderr).join(''));
    const todos = await readJson(path.join(cwd, 'todos.json'));
    assert.deepEqual(todos.map((todo) => todo.id).sort((a, b) => a - b), [1, 2, 3, 4, 5, 6, 7, 8]);
    assert.equal(new Set(todos.map((todo) => todo.text)).size, count);
  });

  it('reports a corrupt todos.json with exit 1 and leaves the file as it was', async () => {
    const file = path.join(cwd, 'todos.json');
    await writeFile(file, '{ not json');

    const result = await node('add', 'Buy groceries');

    assert.equal(result.code, 1);
    assert.match(result.stderr, /is not valid JSON/);
    assert.equal(await readFile(file, 'utf8'), '{ not json');
  });
});

