describe('add command', () => {
  it('adds a todo, prints its id and saves it with id, text, completed and createdAt', async () => {
    assert.deepEqual(await cli('add', 'Buy groceries'), { code: 0, stdout: 'Added todo #1: Buy groceries\n', stderr: '' });
    assert.deepEqual(await readJson(todosFile), [
      { id: 1, text: 'Buy groceries', completed: false, createdAt: FIXED_NOW.toISOString() },
    ]);
  });

  it('gives each new todo the next id', async () => {
    await cli('add', 'one');
    await cli('add', 'two');
    const third = await cli('add', 'three');

    assert.equal(third.stdout, 'Added todo #3: three\n');
    assert.deepEqual((await readJson(todosFile)).map((todo) => todo.id), [1, 2, 3]);
  });

  it('joins several unquoted words into one todo', async () => {
    await cli('add', 'Buy', 'milk', 'and', 'eggs');

    assert.equal((await readJson(todosFile))[0].text, 'Buy milk and eggs');
  });

  it('exits 2 with the add usage on stderr and writes nothing when the text is missing', async () => {
    const result = await cli('add');

    assert.equal(result.code, 2);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /^Error: Missing todo text\nUsage: node index\.js add <text>\n/);
    assert.deepEqual(await readdir(cwd), []);
  });

  it('exits 2 when the text is only whitespace', async () => {
    const result = await cli('add', '   ');

    assert.equal(result.code, 2);
    assert.match(result.stderr, /Todo text cannot be empty/);
  });
});

describe('list command', () => {
  it('says there are no todos yet, exits 0 and does not create todos.json', async () => {
    const result = await cli('list');

    assert.deepEqual(result, {
      code: 0,
      stdout: 'No todos yet. Add one with: node index.js add "Buy groceries"\n',
      stderr: '',
    });
    assert.deepEqual(await readdir(cwd), []);
  });

  it('shows the id, [ ] or [x] status and text of every todo, then a summary', async () => {
    await seed([makeTodo({ id: 1, text: 'Buy groceries' }), makeTodo({ id: 2, text: 'Walk the dog', completed: true })]);

    const result = await cli('list');

    assert.equal(result.code, 0);
    assert.equal(result.stdout, '1. [ ] Buy groceries\n2. [x] Walk the dog\n\n2 todos: 1 pending, 1 done\n');
  });

  it('exits 2 when given arguments it does not accept', async () => {
    const result = await cli('list', 'pending');

    assert.equal(result.code, 2);
    assert.match(result.stderr, /"list" does not take arguments/);
  });
});

describe('complete command', () => {
  beforeEach(() => seed([makeTodo({ id: 1, text: 'Buy groceries' }), makeTodo({ id: 2, text: 'Walk the dog' })]));

  it('marks the todo as done so list shows [x]', async () => {
    assert.deepEqual(await cli('complete', '1'), { code: 0, stdout: 'Completed todo #1: Buy groceries\n', stderr: '' });
    assert.match((await cli('list')).stdout, /^1\. \[x\] Buy groceries\n2\. \[ \] Walk the dog\n/);
  });

  it('reports an already-completed todo and still exits 0', async () => {
    await cli('complete', '2');

    assert.deepEqual(await cli('complete', '2'), {
      code: 0,
      stdout: 'Already completed todo #2: Walk the dog\n',
      stderr: '',
    });
  });

  it('completes several ids in one call', async () => {
    const result = await cli('complete', '2', '1');

    assert.equal(result.stdout, 'Completed todo #2: Walk the dog\nCompleted todo #1: Buy groceries\n');
    assert.ok((await readJson(todosFile)).every((todo) => todo.completed));
  });

  it('exits 2 with the complete usage when the id is missing', async () => {
    const result = await cli('complete');

    assert.equal(result.code, 2);
    assert.match(result.stderr, /Missing todo id\nUsage: node index\.js complete <id> \[<id>\.\.\.\]/);
  });

  it('exits 2 for a non-numeric id', async () => {
    const result = await cli('complete', 'abc');

    assert.equal(result.code, 2);
    assert.match(result.stderr, /Invalid todo id "abc"/);
  });

  it('exits 1 for an unknown id, points to list, and changes nothing', async () => {
    const before = await readJson(todosFile);

    const result = await cli('complete', '1', '99');

    assert.equal(result.code, 1);
