describe('delete command', () => {
  beforeEach(() => seed([makeTodo({ id: 1, text: 'Buy groceries' }), makeTodo({ id: 2, text: 'Walk the dog' })]));

  it('removes the todo so list no longer shows it', async () => {
    assert.deepEqual(await cli('delete', '1'), { code: 0, stdout: 'Deleted todo #1: Buy groceries\n', stderr: '' });
    assert.equal((await cli('list')).stdout, '2. [ ] Walk the dog\n\n1 todo: 1 pending, 0 done\n');
  });

  it('exits 1 for an unknown id and deletes nothing, even when the other ids exist', async () => {
    const result = await cli('delete', '1', '3');

    assert.equal(result.code, 1);
    assert.equal((await readJson(todosFile)).length, 2);
  });

  it('exits 2 with the delete usage when the id is missing', async () => {
    const result = await cli('delete');

    assert.equal(result.code, 2);
    assert.match(result.stderr, /Usage: node index\.js delete <id>/);
  });

  it('exits 2 for a zero id', async () => {
    const result = await cli('delete', '0');

    assert.equal(result.code, 2);
    assert.match(result.stderr, /Invalid todo id "0"/);
  });
});

describe('command dispatch', () => {
  for (const flag of ['help', '--help', '-h']) {
    it(`prints help on stdout and exits 0 for ${flag}`, async () => {
      assert.deepEqual(await cli(flag), { code: 0, stdout: `${HELP_TEXT}\n`, stderr: '' });
    });
  }

  it('documents every command and configuration variable in the help text', () => {
    for (const expected of ['add <text>', 'list', 'complete <id>', 'delete <id>', 'TODO_ID_STRATEGY', 'TODO_MAX_TEXT_LENGTH', 'TODO_MAX_ITEMS', 'TODO_LOCK_TIMEOUT_MS']) {
      assert.ok(HELP_TEXT.includes(expected), `help text should mention ${expected}`);
    }
  });

  it('exits 2 with usage when no command is given', async () => {
    const result = await cli();

    assert.equal(result.code, 2);
    assert.match(result.stderr, /^Error: Missing command\nUsage: node index\.js <command> \[arguments\]/);
  });

  it('exits 2 for an unknown command, including a differently cased one', async () => {
    const names = ['frobnicate', 'ADD', 'toString'];

    const results = await Promise.all(names.map((name) => cli(name)));

    results.forEach((result, index) => {
      assert.equal(result.code, 2);
      assert.match(result.stderr, new RegExp(`Unknown command "${names[index]}"`));
    });
