  });
});

describe('id strategies through the CLI', () => {
  async function addTwoDeleteNewestAddAgain(env) {
    const options = { cwd, env };
    await runCli(['add', 'first'], options);
    await runCli(['add', 'second'], options);
    await runCli(['delete', '2'], options);
    return runCli(['add', 'third'], options);
  }

  it('max (default) reuses the id of a deleted newest todo and stores a plain array', async () => {
    const result = await addTwoDeleteNewestAddAgain({});

    assert.equal(result.stdout, 'Added todo #2: third\n');
    assert.ok(Array.isArray(await readJson(todosFile)));
  });

  it('sequence never reuses an id and stores lastId alongside the todos', async () => {
    const result = await addTwoDeleteNewestAddAgain({ TODO_ID_STRATEGY: 'sequence' });

    assert.equal(result.stdout, 'Added todo #3: third\n');
    const document = await readJson(todosFile);
    assert.equal(document.lastId, 3);
    assert.deepEqual(document.todos.map((todo) => todo.id), [1, 3]);
  });
});

