// Unusual input, limits, and recovery from damaged or contended storage,
// exercised through the public CLI entry point.
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { once } from 'node:events';
import { chmod, mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, it } from 'node:test';

import { formatLockOwner } from '../../src/lock.js';
import { runCli } from '../helpers/cli.js';
import { createTempDir, makeTodo, PERMISSIONS_UNENFORCED, readJson, removeTempDir } from '../helpers/fixtures.js';

let cwd;
let todosFile;

beforeEach(async () => {
  cwd = await createTempDir();
  todosFile = path.join(cwd, 'todos.json');
});

afterEach(async () => {
  await chmod(cwd, 0o700);
  await removeTempDir(cwd);
});

const cli = (...argv) => runCli(argv, { cwd });

async function seed(content) {
  await writeFile(todosFile, typeof content === 'string' ? content : JSON.stringify(content));
}

describe('unicode and unusual text', () => {
  it('round-trips emoji, CJK, right-to-left and accented text through add and list', async () => {
    const texts = ['Buy 🍎 and 🍌', '買い物に行く', 'اشترِ الحليب', 'Café crème', '👨‍👩‍👧 family dinner'];
    // Sequential so ids follow the order of `texts`.
    for (const text of texts) await cli('add', text);

    const { stdout } = await cli('list');

    texts.forEach((text, index) => assert.ok(stdout.includes(`${index + 1}. [ ] ${text}\n`), text));
    assert.deepEqual((await readJson(todosFile)).map((todo) => todo.text), texts);
  });

  it('stores text that looks like a flag or a number as ordinary text', async () => {
    assert.equal((await cli('add', '--help')).stdout, 'Added todo #1: --help\n');
    assert.equal((await cli('add', '42')).stdout, 'Added todo #2: 42\n');
  });

  it('rejects text containing a newline with exit 2 and writes nothing', async () => {
    const result = await cli('add', 'line one\nline two');

    assert.equal(result.code, 2);
    assert.match(result.stderr, /single line/);
    assert.deepEqual(await readdir(cwd), []);
  });

  it('escapes terminal control sequences found in a hand-edited todos.json', async () => {
    await seed([makeTodo({ text: 'evil \u001b]0;pwned\u0007 title' })]);

    const { stdout } = await cli('list');

    assert.ok(stdout.includes('1. [ ] evil \\u001b]0;pwned\\u0007 title'));
    assert.ok(!stdout.includes('\u001b'));
  });
});

describe('length and size limits', () => {
  it('rejects 1,000+ character text under the default 500-character limit with exit 2', async () => {
    const result = await cli('add', 'x'.repeat(1_200));

    assert.equal(result.code, 2);
    assert.match(result.stderr, /1200 characters, maximum is 500/);
    assert.deepEqual(await readdir(cwd), []);
  });

  it('accepts exactly 500 characters by default (boundary)', async () => {
    assert.equal((await cli('add', 'y'.repeat(500))).code, 0);
  });

  it('accepts longer text when TODO_MAX_TEXT_LENGTH is raised', async () => {
    const result = await runCli(['add', 'z'.repeat(2_000)], { cwd, env: { TODO_MAX_TEXT_LENGTH: '5000' } });

    assert.equal(result.code, 0);
    assert.equal((await readJson(todosFile))[0].text.length, 2_000);
  });

  it('refuses to add beyond TODO_MAX_ITEMS with exit 1 and keeps the existing todos', async () => {
    const env = { TODO_MAX_ITEMS: '2' };
    await runCli(['add', 'a'], { cwd, env });
    await runCli(['add', 'b'], { cwd, env });

    const result = await runCli(['add', 'c'], { cwd, env });

    assert.equal(result.code, 1);
    assert.match(result.stderr, /maximum of 2 todos/);
    assert.equal((await readJson(todosFile)).length, 2);
  });
});

describe('unusual ids', () => {
  beforeEach(() => seed([makeTodo({ id: 1 })]));

  it('accepts an id with leading zeros', async () => {
    assert.equal((await cli('complete', '001')).code, 0);
    assert.equal((await readJson(todosFile))[0].completed, true);
  });

  for (const id of ['99999999999999999999', '1.0', '-1', '+1', '1e2', '#1']) {
    it(`rejects the id ${JSON.stringify(id)} with exit 2`, async () => {
      const result = await cli('delete', id);

      assert.equal(result.code, 2);
      assert.match(result.stderr, /Invalid todo id/);
      assert.equal((await readJson(todosFile)).length, 1);
    });
  }

  it('rejects the whole command when one of several ids is malformed', async () => {
    const result = await cli('complete', '1', 'two');

    assert.equal(result.code, 2);
    assert.equal((await readJson(todosFile))[0].completed, false);
  });
});

describe('empty and cleared lists', () => {
  it('reports not-found on an empty list, saying the list is empty', async () => {
    const result = await cli('complete', '1');

    assert.equal(result.code, 1);
    assert.match(result.stderr, /No todo with id #1 \(the list is empty\)/);
  });

  it('keeps a valid empty file and shows the empty message after the last todo is deleted', async () => {
    await cli('add', 'only one');
    await cli('delete', '1');

    assert.equal(await readFile(todosFile, 'utf8'), '[]\n');
    assert.match((await cli('list')).stdout, /^No todos yet\./);
  });

  it('treats a zero-byte todos.json as an empty list and can add to it', async () => {
    await seed('');

    assert.match((await cli('list')).stdout, /^No todos yet\./);
    assert.equal((await cli('add', 'first')).stdout, 'Added todo #1: first\n');
  });
});

describe('damaged or inaccessible storage (error recovery)', () => {
  it('never overwrites a todos.json that is not valid JSON', async () => {
    await seed('[{"id": 1, "text": "half written"');

    const add = await cli('add', 'new');
    const list = await cli('list');

    assert.equal(add.code, 1);
    assert.equal(list.code, 1);
    assert.match(add.stderr, /Fix it, or move it aside to start a new list/);
    assert.equal(await readFile(todosFile, 'utf8'), '[{"id": 1, "text": "half written"');
  });

  it('names the broken item when todos.json has the wrong shape', async () => {
    await seed([makeTodo({ id: 1 }), { id: 2, text: 'no status' }]);

    const result = await cli('list');

    assert.equal(result.code, 1);
    assert.match(result.stderr, /item at index 1 has an invalid "completed"/);
  });

  it('reads a sequence-format file under the default strategy and saves it back as a plain array', async () => {
    await seed({ lastId: 7, todos: [makeTodo({ id: 3 })] });

    assert.equal((await cli('add', 'next')).stdout, 'Added todo #4: next\n');
    assert.ok(Array.isArray(await readJson(todosFile)));
  });

  it('reports a todos.json that is a directory with exit 1', async () => {
    await mkdir(todosFile);

    const result = await cli('list');

    assert.equal(result.code, 1);
    assert.match(result.stderr, /^Error: Could not read /);
  });

  it('reports an unreadable todos.json with exit 1', { skip: PERMISSIONS_UNENFORCED }, async () => {
    await seed([makeTodo()]);
    await chmod(todosFile, 0o000);

    const result = await cli('list');

    assert.equal(result.code, 1);
    assert.match(result.stderr, /permission denied/);
  });

  it('reports a read-only directory on add with exit 1 and keeps the existing todos', { skip: PERMISSIONS_UNENFORCED }, async () => {
    await seed([makeTodo()]);
    await chmod(cwd, 0o500);

    const result = await cli('add', 'cannot save');

    assert.equal(result.code, 1);
    assert.match(result.stderr, /^Error: Could not create lock file/);
    assert.deepEqual(await readJson(todosFile), [makeTodo()]);
  });

  it('recovers a lock left behind by a command that crashed', async () => {
    const crashed = spawn(process.execPath, ['-e', ''], { stdio: 'ignore' });
    await once(crashed, 'exit');
    await writeFile(`${todosFile}.lock`, formatLockOwner({ pid: crashed.pid, token: randomUUID(), hostname: os.hostname() }));

    const result = await cli('add', 'after crash');

    assert.equal(result.code, 0);
    assert.deepEqual(await readdir(cwd), ['todos.json']);
  });

  it('gives up with exit 1 once TODO_LOCK_TIMEOUT_MS passes while a live command holds the lock', async () => {
    const lockFile = `${todosFile}.lock`;
    await writeFile(lockFile, formatLockOwner({ pid: process.pid, token: randomUUID(), hostname: os.hostname() }));

    const result = await runCli(['add', 'blocked'], { cwd, env: { TODO_LOCK_TIMEOUT_MS: '50' } });

    assert.equal(result.code, 1);
    assert.match(result.stderr, /Timed out after 50 ms waiting for .*todos\.json\.lock/);
    assert.deepEqual(await readdir(cwd), ['todos.json.lock']);
  });
});

